import argparse,os,pathlib

def prepare_cache(path,uid=10001,gid=10001):
    path=pathlib.Path(path)
    if path.is_symlink() or not path.is_dir():raise ValueError("cache path must be an existing real directory")
    if uid<=0 or gid<0:raise ValueError("invalid application identity")
    os.chown(path,uid,gid,follow_symlinks=False)
    os.chmod(path,0o750,follow_symlinks=False)
    result=path.stat(follow_symlinks=False)
    return {"path":str(path),"uid":result.st_uid,"gid":result.st_gid,"mode":oct(result.st_mode & 0o777)}

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('path');args=parser.parse_args()
    print(prepare_cache(args.path))
```

原题知识说明：
定位应用实际需要的写路径，在镜像或部署支持的初始化方式中仅赋予该目录合适 UID/GID 和权限，程序代码保持只读。验证普通运行、只读根及挂载场景；不能全盘 chmod777 或恢复 root 作为最终方案，先回退发布保护业务。

